{
  "tasks": [
    {
      "task_id": "T01",
      "title": "计算一组与三组团队的响应分钟中位数并升序排名",
      "business_question": "按团队统计，仅包含“一组”和“三组”，计算各组的“响应分钟”中位数，并按中位数进行升序排名。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心问题（两组的中位数对比及排名），直接支持决策目标。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "一组",
                  "三组"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0005",
                "alias": "response_median"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "response_median",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
